const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Saskatchewan geometry (approximate bounds)
  const saskatchewan = ee.Geometry.Polygon([
    [[-110, 49], [-110, 60], [-101, 60], [-101, 49], [-110, 49]]
  ]);

  // 2. Define date range for August 3, 2025
  const targetDate = '2025-08-03';
  const startDate = '2025-08-03';
  const endDate = '2025-08-04';

  // 3. Try MODIS Thermal Anomalies/Fire daily product
  let fireCollection = ee.ImageCollection('MODIS/061/MOD14A1')
    .filterDate(startDate, endDate)
    .filterBounds(saskatchewan);

  let collectionSize = fireCollection.size().getInfo();
  console.log(`MODIS MOD14A1 Images found: ${collectionSize}`);

  // If MODIS fails, try VIIRS
  if (collectionSize === 0) {
    fireCollection = ee.ImageCollection('MODIS/061/MYD14A1')
      .filterDate(startDate, endDate)
      .filterBounds(saskatchewan);

    collectionSize = fireCollection.size().getInfo();
    console.log(`MODIS MYD14A1 Images found: ${collectionSize}`);
  }

  // If still no data, try FIRMS VIIRS
  if (collectionSize === 0) {
    fireCollection = ee.ImageCollection('FIRMS')
      .filterDate(startDate, endDate)
      .filterBounds(saskatchewan);

    collectionSize = fireCollection.size().getInfo();
    console.log(`FIRMS Images found: ${collectionSize}`);
  }

  if (collectionSize === 0) {
    console.log("No fire detection data available for August 3, 2025.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 4. Process fire data - use FireMask band (7-9 are fire classes)
  const fireImage = fireCollection.first();
  const fireMask = fireImage.select('FireMask').gte(7).and(fireImage.select('FireMask').lte(9));

  // 5. Count fire pixels in Saskatchewan
  const fireStats = fireMask.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: saskatchewan,
    scale: 1000,
    maxPixels: 1e9
  });

  const fireCount = fireStats.get('FireMask').getInfo();

  if (fireCount === null || fireCount === undefined) {
    console.log("Fire count calculation failed.");
    console.log("<answer>C3</answer>");
    return;
  }

  // 6. Validation - check if we have valid data
  const totalPixels = fireMask.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: saskatchewan,
    scale: 1000,
    maxPixels: 1e9
  }).get('FireMask').getInfo();

  console.log(`Total pixels analyzed: ${totalPixels}`);
  console.log(`Active fire detections: ${fireCount}`);

  if (totalPixels === 0) {
    console.log("No valid pixels after processing.");
    console.log("<answer>C2</answer>");
    return;
  }

  // 7. Final answer
  if (fireCount > 120) {
    console.log(`Fire count (${fireCount}) exceeds 120.`);
    console.log("<answer>A</answer>");
  } else {
    console.log(`Fire count (${fireCount}) does not exceed 120.`);
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
